$ErrorActionPreference='Stop';$config=@{};foreach($line in Get-Content -LiteralPath '.env'){if($line -match '^\s*([^#][^=]*)=(.*)$'){$config[$matches[1].Trim()]=$matches[2].Trim().Trim('"')}}
function Json($session,$method,$url,$body=$null){$a=@{Uri="http://localhost:3000$url";Method=$method;WebSession=$session;UseBasicParsing=$true};if($null-ne$body){$a.ContentType='application/json';$a.Body=($body|ConvertTo-Json -Depth 5)};$r=Invoke-WebRequest @a;return($r.Content|ConvertFrom-Json).data}
$admin=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$null=Json $admin 'POST' '/api/v1/auth/login' @{email=$config.SEED_ADMIN_EMAIL;password=$config.SEED_ADMIN_PASSWORD};$projects=Json $admin 'GET' '/api/v1/projects?pageSize=100';$states=Json $admin 'GET' '/api/v1/locations/states';$project=$projects.items|Select-Object -First 1;$state=$states|Where-Object{$_.name-eq'Niger'}|Select-Object -First 1;$email='phase2a.isolation@example.org';$password='Isolation-Test-2026!';
try{$null=Json $admin 'POST' '/api/v1/users' @{firstName='Isolation';lastName='Facilitator';email=$email;password=$password;status='ACTIVE';roleCode='FACILITATOR';projectId=$project.id;stateId=$state.id}}catch{if(-not $_.Exception.Message.Contains('500')){throw}}
$facilitator=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$null=Json $facilitator 'POST' '/api/v1/auth/login' @{email=$email;password=$password};$groups=Json $admin 'GET' '/api/v1/groups?search=CCCRN-NIG-MNA-0001&pageSize=10';$target=$groups.items|Select-Object -First 1;if(-not$target){throw'Target group missing'}
$paths=@("/api/v1/groups/$($target.id)/members","/api/v1/groups/$($target.id)/constitution","/api/v1/groups/$($target.id)/cycles","/api/v1/groups/$($target.id)/officers","/api/v1/groups/$($target.id)/onboarding-status");foreach($path in $paths){$denied=$false;try{$null=Invoke-WebRequest -Uri "http://localhost:3000$path" -WebSession $facilitator -UseBasicParsing}catch{$code=[int]$_.Exception.Response.StatusCode;if($code-eq403){$denied=$true}};if(-not$denied){throw"Expected 403 for $path"};Write-Output "403 isolation: $path PASS"}
$visible=Json $facilitator 'GET' '/api/v1/groups?pageSize=100';if($visible.items.id-contains$target.id){throw'Unauthorized group appeared in facilitator list'};Write-Output 'Unauthorized group list filtering: PASS'
